Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
﻿#include <bits/stdc++.h>
using namespace std;

#define pb push_back
#define mp make_pair
#define fs first
#define sc second
#define sz(a) ((int) (a).size())
#define int64 long long
#define ldb long double
const ldb pi = acos(-1.0);

#define FULL 2
#define OK 1
#define EMPTY 0

int get_state(int a, int b, int c) {
	if ((a == 0) && (b == 0)) {
		if (c == 0) return FULL;
		return EMPTY;
	}
	return OK;
}

int det2(int a, int b, int c, int d) {
	return a * d - b * c;
}

int main() {
	// assert(freopen("input.txt", "r", stdin));
	// assert(freopen("output.txt", "w", stdout));
	int a1, b1, c1, a2, b2, c2;
	scanf("%d%d%d", &a1, &b1, &c1);
	scanf("%d%d%d", &a2, &b2, &c2);
	int s1 = get_state(a1, b1, c1);
	int s2 = get_state(a2, b2, c2);
	if (s1 == EMPTY || s2 == EMPTY) {
		printf("0\n");
		return 0;
	}
	if (s1 == FULL || s2 == FULL) {
		printf("-1\n");
		return 0;
	}
	int d = det2(a1, b1, a2, b2);
	if (d == 0) {
		if (det2(a1, c1, a2, c2) == 0) {
			printf("-1\n");
		} else {
			printf("0\n");
		}
	} else {
		printf("1\n");
	}
	return 0;
}         
